-- FUNCTION: activate_ai_prompt(uuid)
CREATE FUNCTION public.activate_ai_prompt(_prompt_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _target public.ai_prompt_versions%rowtype;
  _active_count integer;
begin
  if not (public.has_role(auth.uid(), 'admin') or public.is_super_admin(auth.uid())) then
    raise exception 'Forbidden: admin role required' using errcode = '42501';
  end if;

  -- Serialise concurrent activations so two requests can never interleave.
  perform pg_advisory_xact_lock(hashtext('public.activate_ai_prompt'));

  select * into _target from public.ai_prompt_versions where id = _prompt_id for update;
  if not found then
    raise exception 'PROMPT_NOT_FOUND' using errcode = 'P0002';
  end if;
  if _target.status = 'active' then
    return; -- already active: nothing to change
  end if;
  if _target.status not in ('draft', 'archived') then
    raise exception 'PROMPT_NOT_ELIGIBLE' using errcode = '22023';
  end if;
  if btrim(coalesce(_target.prompt_text, '')) = '' or btrim(coalesce(_target.model, '')) = '' then
    raise exception 'PROMPT_INVALID' using errcode = '22023';
  end if;

  update public.ai_prompt_versions set status = 'archived'
   where status = 'active' and id <> _prompt_id;
  update public.ai_prompt_versions
     set status = 'active', activated_at = now(), activated_by = auth.uid()
   where id = _prompt_id;

  select count(*) into _active_count from public.ai_prompt_versions where status = 'active';
  if _active_count <> 1 then
    raise exception 'PROMPT_ACTIVATION_FAILED' using errcode = 'P0001';
  end if;
end;
$$;

-- FUNCTION: ai_quota_cleanup()
CREATE FUNCTION public.ai_quota_cleanup() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM public.ai_rate_buckets WHERE window_start < now() - interval '2 days';
  DELETE FROM public.ai_inflight WHERE created_at < now() - interval '2 days';
  DELETE FROM public.ai_conversations WHERE updated_at < now() - interval '2 hours';
  DELETE FROM public.ai_usage_events WHERE created_at < now() - interval '30 days';
  DELETE FROM public.ai_global_usage WHERE day < (now() AT TIME ZONE 'utc')::date - 400;
END;
$$;

-- FUNCTION: ai_release_quota(uuid, integer)
CREATE FUNCTION public.ai_release_quota(_reservation uuid, _actual_tokens integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r public.ai_inflight%ROWTYPE;
BEGIN
  UPDATE public.ai_inflight
     SET released_at = coalesce(released_at, now()),
         actual_tokens = _actual_tokens,
         reconciled = true
   WHERE id = _reservation AND NOT reconciled
  RETURNING * INTO r;
  IF NOT FOUND THEN RETURN; END IF;
  IF _actual_tokens IS NOT NULL AND _actual_tokens >= 0 THEN
    UPDATE public.ai_global_usage
       SET reserved_tokens = greatest(0, reserved_tokens - r.reserved_tokens + _actual_tokens),
           actual_tokens = actual_tokens + _actual_tokens
     WHERE day = r.day;
  END IF;
END;
$$;

-- FUNCTION: ai_reserve_quota(text, text, integer)
CREATE FUNCTION public.ai_reserve_quota(_visitor text, _ip text, _est_tokens integer) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT public.ai_reserve_quota(_visitor, _ip, _est_tokens, NULL, NULL) $$;

-- FUNCTION: ai_reserve_quota(text, text, integer, text, text)
CREATE FUNCTION public.ai_reserve_quota(_visitor text, _ip text, _est_tokens integer, _ip_previous text, _ip_next text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s public.ai_quota_settings%ROWTYPE;
  g public.ai_global_usage%ROWTYPE;
  v_now timestamptz;
  v_day date;
  v_m timestamptz;
  v_h timestamptz;
  v_d timestamptz;
  s_m integer;
  s_h integer;
  s_d integer;
  v_limit text := NULL;
  v_retry integer := 0;
  v_count integer;
  v_id uuid;
  v_last timestamptz;
  v_oldest timestamptz;
  v_ips text[];
BEGIN
  IF _visitor IS NULL OR length(_visitor) < 16 OR _ip IS NULL OR length(_ip) < 16
     OR _est_tokens IS NULL OR _est_tokens < 1 OR _est_tokens > 2000000 THEN
    RAISE EXCEPTION 'invalid quota request';
  END IF;
  -- One transaction-scoped lock across ALL days, not an identifier-derived lock.
  -- The old daily-row lock alone permits overlapping admissions across midnight.
  PERFORM pg_advisory_xact_lock(4301, 7);
  -- Read real time AFTER waiting, not the transaction's potentially stale now().
  v_now := clock_timestamp();
  v_day := (v_now AT TIME ZONE 'utc')::date;
  v_m := date_trunc('minute', v_now);
  v_h := date_trunc('hour', v_now);
  v_d := date_trunc('day', v_now AT TIME ZONE 'utc') AT TIME ZONE 'utc';
  s_m := greatest(1, ceil(extract(epoch FROM (v_m + interval '1 minute' - v_now)))::int);
  s_h := greatest(1, ceil(extract(epoch FROM (v_h + interval '1 hour' - v_now)))::int);
  s_d := greatest(1, ceil(extract(epoch FROM (v_d + interval '1 day' - v_now)))::int);

  SELECT * INTO s FROM public.ai_quota_settings WHERE id;
  IF NOT FOUND THEN RAISE EXCEPTION 'quota settings missing'; END IF;
  IF (s.ip_rolling_limit IS NULL) <> (s.ip_rolling_window_seconds IS NULL) THEN
    RAISE EXCEPTION 'incomplete rolling quota settings';
  END IF;
  IF _ip_previous IS NULL AND _ip_next IS NULL AND s.ip_rolling_limit IS NULL THEN
    v_ips := ARRAY[_ip]; -- Legacy callers allowed only while rolling limits are off.
  ELSE
    IF _ip_previous IS NULL OR length(_ip_previous) < 16
       OR _ip_next IS NULL OR length(_ip_next) < 16
       OR _ip_previous = _ip OR _ip_next = _ip OR _ip_previous = _ip_next THEN
      RAISE EXCEPTION 'network rollover identifiers missing or invalid';
    END IF;
    v_ips := ARRAY[_ip_previous, _ip, _ip_next];
  END IF;

  INSERT INTO public.ai_global_usage (day) VALUES (v_day) ON CONFLICT DO NOTHING;
  SELECT * INTO g FROM public.ai_global_usage WHERE day = v_day FOR UPDATE;

  IF NOT s.enabled THEN
    v_limit := 'disabled'; v_retry := 3600;
  END IF;

  IF v_limit IS NULL THEN
    SELECT count(*) INTO v_count FROM public.ai_inflight
     WHERE visitor_hash = _visitor AND released_at IS NULL AND created_at > v_now - interval '120 seconds';
    IF v_count >= s.concurrent_per_visitor THEN v_limit := 'concurrent_visitor'; v_retry := 5; END IF;
  END IF;
  IF v_limit IS NULL THEN
    SELECT count(*) INTO v_count FROM public.ai_inflight
     WHERE ip_hash = ANY(v_ips) AND released_at IS NULL AND created_at > v_now - interval '120 seconds';
    IF v_count >= s.concurrent_per_ip THEN v_limit := 'concurrent_ip'; v_retry := 5; END IF;
  END IF;
  -- 0007: minimum spacing between admitted turns for one visitor (NULL = off).
  IF v_limit IS NULL AND s.visitor_min_interval_seconds IS NOT NULL THEN
    SELECT max(created_at) INTO v_last FROM public.ai_inflight WHERE visitor_hash = _visitor;
    IF v_last IS NOT NULL AND v_last > v_now - make_interval(secs => s.visitor_min_interval_seconds) THEN
      v_limit := 'visitor_interval';
      v_retry := greatest(1, ceil(extract(epoch FROM (v_last + make_interval(secs => s.visitor_min_interval_seconds) - v_now)))::int);
    END IF;
  END IF;
  -- 0007: rolling (sliding) network window, independent of browser cookies (NULL = off).
-- Counts each admitted reservation once across adjacent daily hashes in the trailing window,
  -- so a burst cannot straddle fixed calendar-minute boundaries.
  IF v_limit IS NULL AND s.ip_rolling_limit IS NOT NULL AND s.ip_rolling_window_seconds IS NOT NULL THEN
    SELECT count(*), min(created_at) INTO v_count, v_oldest FROM public.ai_inflight
     WHERE ip_hash = ANY(v_ips) AND created_at > v_now - make_interval(secs => s.ip_rolling_window_seconds);
    IF v_count >= s.ip_rolling_limit THEN
      v_limit := 'ip_rolling';
      v_retry := greatest(1, ceil(extract(epoch FROM (v_oldest + make_interval(secs => s.ip_rolling_window_seconds) - v_now)))::int);
    END IF;
  END IF;
  IF v_limit IS NULL AND g.requests >= s.global_requests_per_day THEN
    v_limit := 'global_requests'; v_retry := s_d;
  END IF;
  IF v_limit IS NULL AND g.reserved_tokens + _est_tokens > s.global_tokens_per_day THEN
    v_limit := 'global_budget'; v_retry := s_d;
  END IF;

  IF v_limit IS NULL THEN
    SELECT coalesce(max(count),0) INTO v_count FROM public.ai_rate_buckets WHERE scope='visitor' AND key_hash=_visitor AND window_kind='m' AND window_start=v_m;
    IF v_count >= s.visitor_per_minute THEN v_limit := 'visitor_minute'; v_retry := s_m; END IF;
  END IF;
  IF v_limit IS NULL THEN
    SELECT coalesce(max(count),0) INTO v_count FROM public.ai_rate_buckets WHERE scope='visitor' AND key_hash=_visitor AND window_kind='h' AND window_start=v_h;
    IF v_count >= s.visitor_per_hour THEN v_limit := 'visitor_hour'; v_retry := s_h; END IF;
  END IF;
  IF v_limit IS NULL THEN
    SELECT coalesce(max(count),0) INTO v_count FROM public.ai_rate_buckets WHERE scope='visitor' AND key_hash=_visitor AND window_kind='d' AND window_start=v_d;
    IF v_count >= s.visitor_per_day THEN v_limit := 'visitor_day'; v_retry := s_d; END IF;
  END IF;
  IF v_limit IS NULL THEN
    SELECT coalesce(max(count),0) INTO v_count FROM public.ai_rate_buckets WHERE scope='ip' AND key_hash=_ip AND window_kind='m' AND window_start=v_m;
    IF v_count >= s.ip_per_minute THEN v_limit := 'ip_minute'; v_retry := s_m; END IF;
  END IF;
  IF v_limit IS NULL THEN
    SELECT coalesce(max(count),0) INTO v_count FROM public.ai_rate_buckets WHERE scope='ip' AND key_hash=_ip AND window_kind='h' AND window_start=v_h;
    IF v_count >= s.ip_per_hour THEN v_limit := 'ip_hour'; v_retry := s_h; END IF;
  END IF;
  IF v_limit IS NULL THEN
    SELECT coalesce(max(count),0) INTO v_count FROM public.ai_rate_buckets WHERE scope='ip' AND key_hash=_ip AND window_kind='d' AND window_start=v_d;
    IF v_count >= s.ip_per_day THEN v_limit := 'ip_day'; v_retry := s_d; END IF;
  END IF;

  IF v_limit IS NOT NULL THEN
    UPDATE public.ai_global_usage SET rejected = rejected + 1 WHERE day = v_day;
    RETURN jsonb_build_object('ok', false, 'limit', v_limit, 'retry_after', v_retry);
  END IF;

  INSERT INTO public.ai_rate_buckets (scope, key_hash, window_kind, window_start, count) VALUES
    ('visitor', _visitor, 'm', v_m, 1), ('visitor', _visitor, 'h', v_h, 1), ('visitor', _visitor, 'd', v_d, 1),
    ('ip', _ip, 'm', v_m, 1), ('ip', _ip, 'h', v_h, 1), ('ip', _ip, 'd', v_d, 1)
  ON CONFLICT (scope, key_hash, window_kind, window_start) DO UPDATE SET count = public.ai_rate_buckets.count + 1;

  UPDATE public.ai_global_usage
     SET requests = requests + 1, reserved_tokens = reserved_tokens + _est_tokens
   WHERE day = v_day;

  INSERT INTO public.ai_inflight (visitor_hash, ip_hash, day, reserved_tokens, created_at)
  VALUES (_visitor, _ip, v_day, _est_tokens, v_now) RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'reservation_id', v_id);
END;
$$;

-- FUNCTION: can_view_admin(uuid)
CREATE FUNCTION public.can_view_admin(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id
    AND role::text IN ('admin','super_admin','security_auditor'));
$$;

-- FUNCTION: has_role(uuid, public.app_role)
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    select exists (
        select 1
        from public.user_roles
        where user_id = _user_id
          and role = _role
    );
$$;

-- FUNCTION: is_security_auditor(uuid)
CREATE FUNCTION public.is_security_auditor(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role::text = 'security_auditor');
$$;

-- FUNCTION: is_super_admin(uuid)
CREATE FUNCTION public.is_super_admin(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role::text = 'super_admin'
  );
$$;

-- FUNCTION: protect_last_super_admin()
CREATE FUNCTION public.protect_last_super_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  remaining integer;
BEGIN
  IF OLD.role::text = 'super_admin' THEN
    SELECT count(*) INTO remaining
    FROM public.user_roles
    WHERE role::text = 'super_admin' AND id <> OLD.id;
    IF remaining = 0 THEN
      RAISE EXCEPTION 'Cannot remove the last Super Admin';
    END IF;
  END IF;
  RETURN OLD;
END;
$$;

-- FUNCTION: publish_dataset_version(uuid)
CREATE FUNCTION public.publish_dataset_version(_version_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _type public.workbook_type;
  _status public.dataset_status;
  _errors integer;
begin
  if not public.has_role(auth.uid(), 'admin') then
    raise exception 'Forbidden: admin role required';
  end if;

  select workbook_type, status,
         coalesce((validation_summary->>'criticalErrors')::int, 0)
    into _type, _status, _errors
  from public.dataset_versions where id = _version_id for update;

  if _type is null then
    raise exception 'Dataset version not found';
  end if;
  if _status not in ('validated','archived') then
    raise exception 'Only validated or archived versions can be published';
  end if;
  if _errors > 0 then
    raise exception 'Dataset has critical validation errors';
  end if;

  update public.dataset_versions
     set status = 'archived', superseded_at = now(), updated_at = now()
   where workbook_type = _type and status = 'published';

  update public.dataset_versions
     set status = 'published', published_at = now(), published_by = auth.uid(), updated_at = now()
   where id = _version_id;
end;
$$;

-- FUNCTION: update_updated_at_column()
CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- TABLE: ai_conversations
CREATE TABLE public.ai_conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    visitor_hash text NOT NULL,
    turns integer DEFAULT 0 NOT NULL,
    history jsonb DEFAULT '[]'::jsonb NOT NULL,
    proposed jsonb DEFAULT '{"labs": []}'::jsonb NOT NULL,
    expanded_section_keys jsonb DEFAULT '[]'::jsonb NOT NULL,
    prompt_version_id uuid,
    prompt_version_number integer,
    model text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

-- TABLE: ai_global_usage
CREATE TABLE public.ai_global_usage (
    day date NOT NULL,
    requests integer DEFAULT 0 NOT NULL,
    reserved_tokens bigint DEFAULT 0 NOT NULL,
    actual_tokens bigint DEFAULT 0 NOT NULL,
    rejected integer DEFAULT 0 NOT NULL
);

-- TABLE: ai_inflight
CREATE TABLE public.ai_inflight (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    visitor_hash text NOT NULL,
    ip_hash text NOT NULL,
    day date NOT NULL,
    reserved_tokens integer NOT NULL,
    actual_tokens integer,
    reconciled boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    released_at timestamp with time zone
);

-- TABLE: ai_prompt_versions
CREATE TABLE public.ai_prompt_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    prompt_name text DEFAULT 'One Health AI Lab Assistant'::text NOT NULL,
    prompt_text text NOT NULL,
    model text DEFAULT 'gpt-4o-mini'::text NOT NULL,
    version_number integer NOT NULL,
    status public.prompt_status DEFAULT 'draft'::public.prompt_status NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_by uuid,
    activated_at timestamp with time zone
);

-- TABLE: ai_quota_settings
CREATE TABLE public.ai_quota_settings (
    id boolean DEFAULT true NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    visitor_per_minute integer DEFAULT 6 NOT NULL,
    visitor_per_hour integer DEFAULT 40 NOT NULL,
    visitor_per_day integer DEFAULT 120 NOT NULL,
    ip_per_minute integer DEFAULT 15 NOT NULL,
    ip_per_hour integer DEFAULT 120 NOT NULL,
    ip_per_day integer DEFAULT 400 NOT NULL,
    concurrent_per_visitor integer DEFAULT 1 NOT NULL,
    concurrent_per_ip integer DEFAULT 4 NOT NULL,
    global_requests_per_day integer DEFAULT 2000 NOT NULL,
    global_tokens_per_day bigint DEFAULT 3000000 NOT NULL,
    alert_threshold_1 integer DEFAULT 75 NOT NULL,
    alert_threshold_2 integer DEFAULT 90 NOT NULL,
    max_input_chars integer DEFAULT 2000 NOT NULL,
    max_output_tokens integer DEFAULT 4000 NOT NULL,
    max_turns integer DEFAULT 40 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    ip_rolling_limit integer,
    ip_rolling_window_seconds integer,
    visitor_min_interval_seconds integer,
    CONSTRAINT ai_quota_settings_alert_threshold_1_check CHECK (((alert_threshold_1 >= 1) AND (alert_threshold_1 <= 100))),
    CONSTRAINT ai_quota_settings_alert_threshold_2_check CHECK (((alert_threshold_2 >= 1) AND (alert_threshold_2 <= 100))),
    CONSTRAINT ai_quota_settings_concurrent_per_ip_check CHECK (((concurrent_per_ip >= 1) AND (concurrent_per_ip <= 100))),
    CONSTRAINT ai_quota_settings_concurrent_per_visitor_check CHECK (((concurrent_per_visitor >= 1) AND (concurrent_per_visitor <= 20))),
    CONSTRAINT ai_quota_settings_global_requests_per_day_check CHECK (((global_requests_per_day >= 1) AND (global_requests_per_day <= 10000000))),
    CONSTRAINT ai_quota_settings_global_tokens_per_day_check CHECK (((global_tokens_per_day >= 1000) AND (global_tokens_per_day <= '10000000000'::bigint))),
    CONSTRAINT ai_quota_settings_id_check CHECK (id),
    CONSTRAINT ai_quota_settings_ip_per_day_check CHECK (((ip_per_day >= 1) AND (ip_per_day <= 1000000))),
    CONSTRAINT ai_quota_settings_ip_per_hour_check CHECK (((ip_per_hour >= 1) AND (ip_per_hour <= 100000))),
    CONSTRAINT ai_quota_settings_ip_per_minute_check CHECK (((ip_per_minute >= 1) AND (ip_per_minute <= 10000))),
    CONSTRAINT ai_quota_settings_ip_rolling_limit_check CHECK (((ip_rolling_limit >= 1) AND (ip_rolling_limit <= 10000))),
    CONSTRAINT ai_quota_settings_ip_rolling_window_seconds_check CHECK (((ip_rolling_window_seconds >= 10) AND (ip_rolling_window_seconds <= 3600))),
    CONSTRAINT ai_quota_settings_max_input_chars_check CHECK (((max_input_chars >= 50) AND (max_input_chars <= 20000))),
    CONSTRAINT ai_quota_settings_max_output_tokens_check CHECK (((max_output_tokens >= 256) AND (max_output_tokens <= 32000))),
    CONSTRAINT ai_quota_settings_max_turns_check CHECK (((max_turns >= 1) AND (max_turns <= 500))),
    CONSTRAINT ai_quota_settings_visitor_min_interval_seconds_check CHECK (((visitor_min_interval_seconds >= 1) AND (visitor_min_interval_seconds <= 300))),
    CONSTRAINT ai_quota_settings_visitor_per_day_check CHECK (((visitor_per_day >= 1) AND (visitor_per_day <= 100000))),
    CONSTRAINT ai_quota_settings_visitor_per_hour_check CHECK (((visitor_per_hour >= 1) AND (visitor_per_hour <= 10000))),
    CONSTRAINT ai_quota_settings_visitor_per_minute_check CHECK (((visitor_per_minute >= 1) AND (visitor_per_minute <= 1000)))
);

