    make_delivery_completed_at timestamp with time zone,
    make_http_status integer,
    make_error_summary text,
    make_attempt_count integer DEFAULT 0 NOT NULL,
    make_response_summary jsonb,
    report_status text,
    report_storage_path text,
    report_generated_at timestamp with time zone,
    report_version integer DEFAULT 0 NOT NULL,
    report_error text,
    email_status text,
    email_sent_at timestamp with time zone,
    email_error text,
    email_attempt_count integer DEFAULT 0 NOT NULL,
    email_recipients jsonb,
    report_auto_attempts integer DEFAULT 0 NOT NULL,
    report_claimed_at timestamp with time zone,
    email_claimed_at timestamp with time zone,
    CONSTRAINT calculator_submissions_email_status_check CHECK (((email_status IS NULL) OR (email_status = ANY (ARRAY['pending'::text, 'sending'::text, 'sent'::text, 'failed'::text])))),
    CONSTRAINT calculator_submissions_report_status_check CHECK (((report_status IS NULL) OR (report_status = ANY (ARRAY['pending'::text, 'generating'::text, 'generated'::text, 'failed'::text]))))
);

-- TABLE: dataset_versions
CREATE TABLE public.dataset_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workbook_type public.workbook_type NOT NULL,
    version_number integer NOT NULL,
    status public.dataset_status DEFAULT 'uploaded'::public.dataset_status NOT NULL,
    original_filename text NOT NULL,
    storage_path text,
    file_size bigint,
    checksum text,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    uploaded_by uuid,
    validated_at timestamp with time zone,
    validation_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    validation_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    published_at timestamp with time zone,
    published_by uuid,
    superseded_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

