-- POLICY: settings Admins can manage settings
CREATE POLICY "Admins can manage settings" ON public.settings TO onehealth_authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));

-- POLICY: audit_log Admins can read audit log
CREATE POLICY "Admins can read audit log" ON public.audit_log FOR SELECT TO onehealth_authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role));

-- POLICY: sales_report_recipients Admins delete sales recipients
CREATE POLICY "Admins delete sales recipients" ON public.sales_report_recipients FOR DELETE TO onehealth_authenticated USING ((public.has_role(auth.uid(), 'admin'::public.app_role) OR public.is_super_admin(auth.uid())));

-- POLICY: sales_report_recipients Admins insert sales recipients
CREATE POLICY "Admins insert sales recipients" ON public.sales_report_recipients FOR INSERT TO onehealth_authenticated WITH CHECK ((public.has_role(auth.uid(), 'admin'::public.app_role) OR public.is_super_admin(auth.uid())));

-- POLICY: ai_prompt_versions Admins manage ai prompts
CREATE POLICY "Admins manage ai prompts" ON public.ai_prompt_versions TO onehealth_authenticated USING (public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (public.has_role(auth.uid(), 'admin'::public.app_role));

